import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotSame;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class AnnotationIntrospector_refineDeserializationType_TriageGen0Test {

    private AnnotationIntrospector introspector;
    private MapperConfig<?> config;
    private TypeFactory typeFactory;
    private Annotated annotated;

    @Before
    public void setUp() {
        // We need a concrete implementation of AnnotationIntrospector because it's abstract
        // and the method we are testing is actually implemented in a specific subclass 
        // or we mock the behavior of the calls the method makes to other methods in the same class.
        // However, the provided code snippet is the implementation itself.
        // To test this logic, we must mock the 'find...' methods.
        introspector = mock(AnnotationIntrospector.class, Mockito.CALLS_REAL_METHODS);
        config = mock(MapperConfig.class);
        typeFactory = TypeFactory.defaultInstance();
        annotated = mock(Annotated.class);

        when(config.getTypeFactory()).thenReturn(typeFactory);
        when(annotated.getName()).thenReturn("testAnnotation");
    }

    @Test
    public void testRefineDeserializationType_NoChanges() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(String.class);

        // Mock find methods to return null (no refinement)
        when(introspector.findDeserializationType(any(), any())).thenReturn(null);
        when(introspector.findDeserializationKeyType(any(), any())).thenReturn(null);
        when(introspector.findDeserializationContentType(any(), any())).thenReturn(null);

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        assertEquals(baseType, result);
    }

    @Test
    public void testRefineDeserializationType_RefineMainType() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(Object.class);
        Class<?> refinedClass = String.class;

        when(introspector.findDeserializationType(annotated, baseType)).thenReturn(refinedClass);
        when(introspector.findDeserializationKeyType(any(), any())).thenReturn(null);
        when(introspector.findDeserializationContentType(any(), any())).thenReturn(null);

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        assertEquals(refinedClass, result.getRawClass());
        assertNotSame(baseType, result);
    }

    @Test
    public void testRefineDeserializationType_RefineMapKey() throws JsonMappingException {
        // Map<Object, Object>
        JavaType baseType = typeFactory.constructMapType(HashMap.class, Object.class, Object.class);
        Class<?> refinedKeyClass = Integer.class;

        when(introspector.findDeserializationType(any(), any())).thenReturn(null);
        when(introspector.findDeserializationKeyType(annotated, baseType.getKeyType())).thenReturn(refinedKeyClass);
        when(introspector.findDeserializationContentType(any(), any())).thenReturn(null);

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        assertEquals(refinedKeyClass, result.getKeyType().getRawClass());
        assertEquals(Object.class, result.getContentType().getRawClass());
    }

    @Test
    public void testRefineDeserializationType_RefineMapContentType() throws JsonMappingException {
        // Map<Object, Object>
        JavaType baseType = typeFactory.constructMapType(HashMap.class, Object.class, Object.class);
        Class<?> refinedValueClass = String.class;

        when(introspector.findDeserializationType(any(), any())).thenReturn(null);
        when(introspector.findDeserializationKeyType(any(), any())).thenReturn(null);
        when(introspector.findDeserializationContentType(annotated, baseType.getContentType())).thenReturn(refinedValueClass);

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        assertEquals(Object.class, result.getKeyType().getRawClass());
        assertEquals(refinedValueClass, result.getContentType().getRawClass());
    }

    @Test
    public void testRefineDeserializationType_RefineCollectionContentType() throws JsonMappingException {
        // List<Object>
        JavaType baseType = typeFactory.constructCollectionType(java.util.ArrayList.class, Object.class);
        Class<?> refinedValueClass = Double.class;

        when(introspector.findDeserializationType(any(), any())).thenReturn(null);
        when(introspector.findDeserializationKeyType(any(), any())).thenReturn(null);
        when(introspector.findDeserializationContentType(annotated, baseType.getContentType())).thenReturn(refinedValueClass);

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        assertEquals(refinedValueClass, result.getContentType().getRawClass());
    }

    @Test(expected = JsonMappingException.class)
    public void testRefineDeserializationType_ExceptionOnMainTypeRefinement() throws JsonMappingException {
        // Use a type that will cause IllegalArgumentException when constructing specialized type
        // e.g., trying to narrow a non-container type in a way that violates Jackson constraints
        // But since we can't easily trigger the internal TF exception without specific types, 
        // we mock a scenario where the class provided is incompatible.

        JavaType baseType = typeFactory.constructType(String.class);
        // Passing a class that cannot be a sub-type of String to constructSpecializedType
        // Note: In practice, constructSpecializedType checks if the new class is a subclass.
        when(introspector.findDeserializationType(any(), any())).thenReturn(Integer.class);

        introspector.refineDeserializationType(config, annotated, baseType);
    }

    @Test(expected = JsonMappingException.class)
    public void testRefineDeserializationType_ExceptionOnKeyTypeRefinement() throws JsonMappingException {
        JavaType baseType = typeFactory.constructMapType(HashMap.class, String.class, Object.class);

        when(introspector.findDeserializationType(any(), any())).thenReturn(null);
        // Force an incompatible key type refinement
        when(introspector.findDeserializationKeyType(any(), any())).thenReturn(Integer.class); 
        // String -> Integer is generally okay for specialized type, 
        // but we want to trigger the catch block.

        // To trigger the catch, we need the TypeFactory to throw IllegalArgumentException.
        // We can simulate this by mocking the TypeFactory if we weren't using the real one,
        // but here we'll rely on passing a type that violates the specialized type contract.
        // Forcing an error via a null or incompatible structure:
        when(introspector.findDeserializationKeyType(any(), any())).thenThrow(new IllegalArgumentException("Mocked failure"));

        introspector.refineDeserializationType(config, annotated, baseType);
    }

    @Test(expected = JsonMappingException.class)
    public void testRefineDeserializationType_ExceptionOnContentTypeRefinement() throws JsonMappingException {
        JavaType baseType = typeFactory.constructCollectionType(java.util.ArrayList.class, String.class);

        when(introspector.findDeserializationType(any(), any())).thenReturn(null);
        when(introspector.findDeserializationKeyType(any(), any())).thenReturn(null);
        // Simulate failure during content type refinement
        when(introspector.findDeserializationContentType(any(), any())).thenThrow(new IllegalArgumentException("Mocked failure"));

        introspector.refineDeserializationType(config, annotated, baseType);
    }

    @Test
    public void testRefineDeserializationType_MainTypeAlreadyMatches() throws JsonMappingException {
        JavaType baseType = typeFactory.constructType(String.class);

        // findDeserializationType returns the same class
        when(introspector.findDeserializationType(annotated, baseType)).thenReturn(String.class);
        when(introspector.findDeserializationKeyType(any(), any())).thenReturn(null);
        when(introspector.findDeserializationContentType(any(), any())).thenReturn(null);

        JavaType result = introspector.refineDeserializationType(config, annotated, baseType);

        // Should return baseType because type.hasRawClass(valueClass) is true
        assertEquals(baseType, result);
    }
}
